267	/**
268	 * Moves the claim to the status the action leads to; refuses a change its status does not allow, and an open,
269	 * settle or void by a role the sheet's permission matrix does not allow it to. Opening gives
270	 * the claim the sheet's next number (or, while the sheet's period numbering is on, the next in its period: <period>-<n>,
271	 * X-<n> for a claim in no period) and records who opened it; a voided claim keeps its number (never reused). The one who opened a
272	 * claim cannot settle it, and a clerk (any name not made a steward) settles a claim only when its due is at or below
273	 * the sheet's clerk limit (a due of n/a is within any limit; no limit when the sheet has none): a clerk settling one
274	 * above it leaves it PENDING instead. Only a steward approves a PENDING claim (it is settled, its due fixed at its live
275	 * figure then) or rejects it, with a reason that is not blank (it is OPEN again); the one who opened it cannot approve it. Settling fixes the claim's due at the rate of the grade its
276	 * person had on the claim's date, in force on the claim's date, at least the sheet's floor (or at the figure its person's last statement bound it to), plus its late charge on the sheet's today (none when no rate applies then, so it stays live). A claim deferred until after the sheet's today cannot be settled. A claim whose due is above the sheet's proof threshold in force on the claim's date cannot be settled or approved while it has no proof — refused before the clerk limit is considered. A claim dated in a closed period cannot change status. Returns the claim's number for the
277	 * audit.
278	 */
279	public class ApplyClaimStatus {
280	    public String apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
281	            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
282	            @Val Sheet sheet, RoleRepository roles,
283	            @RequestHeader(name = "X-User", required = false) String userHeader,
284	            @RequestParam(name = "reason", required = false) String reason) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
285	        String user = AuditUser.decode(userHeader);
286	        if (periods.isClosedOn(claim.getSheetId(), claim.getDate())) {
287	            throw new ClaimStatusException("A claim in a closed period cannot change status.");
288	        }
289	        String role = roles.roleOf(claim.getSheetId(), user);
290	        if (("open".equals(action) || "settle".equals(action) || "void".equals(action)) && !sheet.allows(action, role)) {
291	            throw new ClerkLimitException("A " + role + " cannot " + action + " a claim.");
292	        }
293	        if ("open".equals(action) && claim.getStatus().after(action) != null) {
294	            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
295	            boolean perPeriod = sheet.periodNumberingOn();
296	            if (perPeriod) {
297	                repository.lockSheet(claim.getSheetId());
298	            } else {
299	                repository.takeNextNumber(claim.getSheetId());
300	            }
301	            entityManager.refresh(claim);
302	            ClaimStatus next = check(claim, action);
303	            if (perPeriod) {
304	                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
305	                        .filter(p -> p.contains(claim.getDate())).map(Period::getName).findFirst().orElse(null);
306	                String seq = prefix == null ? "X" : "P:" + prefix;
307	                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
308	            } else {
309	                claim.setNumber(String.valueOf(repository.lastNumber(claim.getSheetId())));
310	            }
311	            claim.setStatus(next);
312	            claim.setOpenedBy(user);
313	        } else {
314	            ClaimStatus next = check(claim, action);
315	            boolean steward = Role.STEWARD.equals(role);
316	            if (("approve".equals(action) || "reject".equals(action)) && !steward) {
317	                throw new ClerkLimitException("Only a steward can approve or reject a pending claim.");
318	            }
319	            if ("reject".equals(action) && (reason == null || reason.isBlank())) {
320	                throw new ClaimStatusException("A rejection needs a reason.");
321	            }
322	            if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
323	                throw new ClaimStatusException("A deferred claim cannot be settled until the sheet's today reaches its date.");
324	            }
325	            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
326	                throw new ClaimStatusException("The one who opened a claim cannot settle or approve it.");
327	            }
328	            if (next == ClaimStatus.SETTLED) {
329	                BigDecimal due = people.findById(claim.getPersonId())
330	                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
331	                                grades.gradesOf(p), sheet).due(claim))
332	                        .orElse(null);
333	                BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
334	                if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
335	                    throw new ProofRequiredException("A claim whose due is above the proof threshold needs a proof to be settled or approved.");
336	                }
337	                BigDecimal limit = sheet.getClerkLimit();
338	                if ("settle".equals(action) && limit != null && due != null && due.compareTo(limit) > 0 && !steward) {
339	                    next = ClaimStatus.PENDING;
340	                } else {
341	                    claim.setDue(due);
342	                }
343	            }
344	            claim.setStatus(next);
345	        }
346	        repository.saveAndFlush(claim);
347	        return claim.getNumber();
348	    }
349	
350	    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
351	        ClaimStatus next = claim.getStatus().after(action);
352	        if (next == null) {
353	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
354	        }
355	        return next;
356	    }
357	}
