478	 * the sheet's today and the claim's due as the screen works it out now (n/a when it has none). */
479	public class LogClaimStatus {
480	    public void log(@Val Claim claim, @Val Sheet sheet, ClaimLogRepository log, PersonRepository people,
481	            RateRepository rates, PersonGradeRepository grades,
482	            @RequestHeader(name = "X-User", required = false) String user) {
