499	/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
500	public final class ClaimRules {
501	
502	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
503	
504	    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");
505	
506	    private ClaimRules() {
507	    }
508	
509	    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
510	    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField)
511	            throws InvalidClaimException {
512	        String amount = amountField == null ? "" : amountField.trim();
513	        String date = dateField == null ? "" : dateField.trim();
514	        String note = noteField == null ? "" : noteField.trim();
515	        String corrects = correctsField == null ? "" : correctsField.trim();
516	        if (!AMOUNT.matcher(amount).matches()) {
517	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
518	        }
519	        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
520	            throw new InvalidClaimException("Corrects must be a claim number.");
521	        }
522	        BigDecimal value = new BigDecimal(amount).setScale(2);
523	        if (value.signum() < 0 && corrects.isEmpty()) {
524	            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
525	        }
526	        if (value.signum() >= 0 && !corrects.isEmpty()) {
527	            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
528	        }
529	        LocalDate parsed = null;
530	        if (!date.isEmpty()) {
531	            try {
532	                parsed = LocalDate.parse(date);
533	            } catch (DateTimeParseException e) {
534	                throw new InvalidClaimException("Not a date: " + date);
535	            }
536	        }
537	        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects);
538	    }
539	
540	    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. */
541	    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
542	            PeriodRepository periods, PersonGradeRepository grades) throws InvalidClaimException {
543	        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
544	        if (periods.isClosedOn(sheet.getId(), date)) {
545	            throw new InvalidClaimException("No claim can be added in a closed period.");
546	        }
547	        if (person.retiredOn(date)) {
548	            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
549	        }
550	        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
551	        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
552	        claim.setCorrectsDate(correctsDate);
553	        claim.setDueBy(date.plusDays(sheet.termsFor(grades.gradesOf(person).on(date), date)));
554	        return claim;
555	    }
556	
557	    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
558	    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
559	            RateRepository rates, PersonGradeRepository grades, String by) {
560	        BigDecimal due = people.findById(claim.getPersonId())
561	                .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
562	                        grades.gradesOf(p), sheet).due(claim))
563	                .orElse(null);
564	        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
565	    }
566	}
