580	    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);
581	
582	    /** The sheet's claims in the order they are listed: newest first, a moved claim as its new person's newest. */
583	    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);
584	
585	    /** Lists the claim as the newest: gives it the next listing key. */
586	    @Modifying
587	    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
588	    int relist(@Param("id") Long id);
589	
590	    /** The person's claims, newest first. */
591	    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);
592	
593	    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);
594	
595	    /** The person's claims given this number (at most one: numbers are never reused on a sheet). */
596	    List<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);
597	
598	    /** Refuses a correction unless the claim it corrects is a SETTLED claim of the same person; gives that
599	     *  claim's date (null when it is not a correction). */
600	    default LocalDate checkCorrects(String sheetId, Long personId, String corrects) throws InvalidClaimException {
601	        if (corrects == null) {
602	            return null;
603	        }
604	        return findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects).stream()
605	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).map(Claim::getDate).findFirst()
606	                .orElseThrow(() -> new InvalidClaimException("A correction must name a settled claim of the same person."));
607	    }
608	
609	    /** Takes the sheet's next claim number; the update locks the sheet's row until the transaction ends, so
610	     * two claims opened at once are numbered one after the other. */
611	    @Modifying
612	    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :sheetId",
613	            nativeQuery = true)
614	    int takeNextNumber(@Param("sheetId") String sheetId);
615	
616	    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :sheetId", nativeQuery = true)
617	    int lastNumber(@Param("sheetId") String sheetId);
618	
619	    /** Locks the sheet's row until the transaction ends without taking a number, so two claims opened at once in
620	     *  one per-period sequence are numbered one after the other. */
621	    @Modifying
622	    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :sheetId", nativeQuery = true)
623	    int lockSheet(@Param("sheetId") String sheetId);
624	
625	    /** The last number given out in one of the sheet's per-period sequences; null when it has given none. */
626	    @Query(value = "SELECT last_number FROM claim_sequence WHERE sheet_id = :sheetId AND seq = :seq", nativeQuery = true)
627	    Integer lastInSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
628	
629	    @Modifying
630	    @Query(value = "INSERT INTO claim_sequence (sheet_id, seq, last_number) VALUES (:sheetId, :seq, 1)", nativeQuery = true)
631	    int startSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
632	
633	    @Modifying
634	    @Query(value = "UPDATE claim_sequence SET last_number = last_number + 1 WHERE sheet_id = :sheetId AND seq = :seq",
635	            nativeQuery = true)
636	    int advanceSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);
637	
638	    /** Takes the next number in one of the sheet's per-period sequences (from 1); call with the sheet locked. */
639	    default int takeNextInSequence(String sheetId, String seq) {
640	        Integer last = lastInSequence(sheetId, seq);
641	        if (last == null) {
642	            startSequence(sheetId, seq);
643	            return 1;
644	        }
645	        advanceSequence(sheetId, seq);
646	        return last + 1;
647	    }
648	}
