package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;

/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
public final class ClaimRules {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");

    private ClaimRules() {
    }

    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField)
            throws InvalidClaimException {
        String amount = amountField == null ? "" : amountField.trim();
        String date = dateField == null ? "" : dateField.trim();
        String note = noteField == null ? "" : noteField.trim();
        String corrects = correctsField == null ? "" : correctsField.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Corrects must be a claim number.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects);
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), date)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setDueBy(date.plusDays(sheet.termsFor(grades.gradesOf(person).on(date), date)));
        return claim;
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in the order they are listed: newest first, a moved claim as its new person's newest. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    /** Lists the claim as the newest: gives it the next listing key. */
    @Modifying
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
    int relist(@Param("id") Long id);

    /** The person's claims, newest first. */
    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The person's claims given this number (at most one: numbers are never reused on a sheet). */
    List<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** Refuses a correction unless the claim it corrects is a SETTLED claim of the same person; gives that
     *  claim's date (null when it is not a correction). */
    default LocalDate checkCorrects(String sheetId, Long personId, String corrects) throws InvalidClaimException {
        if (corrects == null) {
            return null;
        }
        return findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects).stream()
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).map(Claim::getDate).findFirst()
                .orElseThrow(() -> new InvalidClaimException("A correction must name a settled claim of the same person."));
    }

    /** Takes the sheet's next claim number; the update locks the sheet's row until the transaction ends, so
     * two claims opened at once are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :sheetId",
            nativeQuery = true)
    int takeNextNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastNumber(@Param("sheetId") String sheetId);

    /** Locks the sheet's row until the transaction ends without taking a number, so two claims opened at once in
     *  one per-period sequence are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :sheetId", nativeQuery = true)
    int lockSheet(@Param("sheetId") String sheetId);

    /** The last number given out in one of the sheet's per-period sequences; null when it has given none. */
    @Query(value = "SELECT last_number FROM claim_sequence WHERE sheet_id = :sheetId AND seq = :seq", nativeQuery = true)
    Integer lastInSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    @Modifying
    @Query(value = "INSERT INTO claim_sequence (sheet_id, seq, last_number) VALUES (:sheetId, :seq, 1)", nativeQuery = true)
    int startSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    @Modifying
    @Query(value = "UPDATE claim_sequence SET last_number = last_number + 1 WHERE sheet_id = :sheetId AND seq = :seq",
            nativeQuery = true)
    int advanceSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    /** Takes the next number in one of the sheet's per-period sequences (from 1); call with the sheet locked. */
    default int takeNextInSequence(String sheetId, String seq) {
        Integer last = lastInSequence(sheetId, seq);
        if (last == null) {
            startSequence(sheetId, seq);
            return 1;
        }
        advanceSequence(sheetId, seq);
        return last + 1;
    }
}
