package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Notes the sheet's figures before the change, so the audit can tell afterwards which of them moved. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades, Out<Rollup> before) {
        before.set(Rollup.of(sheetId, sheets, people, claims, rates, grades));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records, after the change's own lines, each person whose figures the change moved, then the sheet's totals
 *  when they moved. */
public class AuditRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        Rollup now = Rollup.of(sheetId, sheets, people, claims, rates, grades);
        now.changesSince(before, sheetId, AuditUser.decode(user)).forEach(audit::record);
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow (or an unknown action). */
public class ClaimStatusException extends Exception {
    public ClaimStatusException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the re-settle, once it is saved: the claim's line, then the due it had and the one it has now. */
public class AuditClaimResettled {
    public void audit(@Parameter Resettled resettled, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_RESETTLED", claim, person, AuditUser.decode(user))
                + " old=" + shown(resettled.old()) + " new=" + shown(resettled.now()));
    }

    private static String shown(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }
}
